package com.vddon;

import java.util.HashMap;
import java.util.Map;

// Generated at build time from the wrapped site's HTML/CSS/JS. Each
// file's bytes are stored base64-encoded as a compiled string constant
// (part of classes.dex), not as a loose file under assets/.
// MainActivity's shouldInterceptRequest override (see EMBED_HOST) decodes
// these on demand to feed the WebView, in place of the OS resolving
// file:///android_asset/ requests against a real assets/ folder.
public final class EmbeddedAssets {
    // Joins base64 chunks at class-init time. Deliberately NOT string
    // concatenation on the call site (see the comment above each F<n>
    // field) -- a method call is not a compile-time constant expression,
    // so javac can't fold these chunks back into one oversized constant.
    private static String join(String... parts) {
        StringBuilder sb = new StringBuilder();
        for (String p : parts) sb.append(p);
        return sb.toString();
    }

    private static final String F0 = join(
            "",
            UrlObfuscator.decode(new int[] { 100, 24, 93, 181, 242, 248, 208, 125, 125, 43, 9, 234, 251, 241, 163, 121, 125, 12, 7, 12, 249, 253, 143, 158, 116, 113, 57, 30, 220, 129, 224, 201, 67, 105, 23, 4, 239, 199, 165, 130, 101, 20, 112, 46, 225, 245, 165, 130, 167, 100, 127, 104, 54, 247, 239, 178, 174, 108, 123, 61, 56, 214, 243, 228, 162, 89, 100, 120, 39, 201, 205, 134, 180, 94, 107, 61, 41, 251, 205, 164, 143, 173, 122, 76, 11, 46, 172, 211, 181, 196, 91, 5, 49, 37, 199, 197, 171, 168, 121, 74, 6, 34, 238, 209, 157, 177, 75, 78, 14, 80, 200, 207, 242, 150, 154, 100, 98, 14, 32, 235, 253, 230, 164, 126, 105, 22, 48, 254, 228, 152, 221, 99, 115, 48, 43, 188, 234, 171, 179, 110, 122, 56, 47, 233, 212, 250, 159, 200, 86, 109, 19, 20, 219, 245, 182, 197, 74, 75, 31, 34, 197, 215, 166, 156, 92, 27, 113, 31, 226, 226, 143, 136, 90, 16, 12, 26, 38, 247, 218, 171, 158, 94, 127, 49, 57, 213, 194, 186, 162, 87, 0, 10, 60, 247, 206, 188, 179, 94, 24, 34, 5, 180, 144, 169, 130, 85, 69, 38, 60, 54, 215, 202, 129, 151, 117, 75, 13, 32, 172, 195, 178, 165, 92, 67, 21, 3, 203, 158, 170, 189, 71, 94, 37, 13, 233, 208, 153, 211, 117, 70, 114, 22, 26, 229, 225, 141, 183, 114, 122, 100, 60, 251, 254, 154, 150, 104, 118, 35, 32, 255, 225, 176, 172, 58, 118, 3, 32, 234, 232, 148, 209, 57, 70, 12, 100, 9, 193, 215, 181, 150, 79, 5, 23, 13, 241, 128, 139, 128, 109, 105, 27, 10, 232, 237, 165, 130, 72, 92, 50, 18, 224, 144, 143, 153, 158, 70, 127, 108, 43, 240, 206, 174, 174, 123, 12, 63, 22, 198, 133, 232, 163, 60, 69, 124, 9, 221, 222, 227 }, 47));

    private static final Map<String, String> MAP = new HashMap<>();
    static {
        MAP.put(UrlObfuscator.decode(new int[] { 41, 49, 26, 248, 196, 245, 146, 109, 85, 59 }, 64), F0);
    }

    // rel: path as it would have appeared under assets/, e.g. "index.html"
    // or "css/style.css". Returns null if nothing was embedded at that path.
    public static byte[] get(String rel) {
        String b64 = MAP.get(rel);
        if (b64 == null) return null;
        byte[] raw = android.util.Base64.decode(b64, android.util.Base64.DEFAULT);
        return raw;
    }

    private EmbeddedAssets() {}
}
